/* ================= V46 ================= */
/* ---------- status colours: live green, completed teal, all done deep green ---------- */
Object.assign(EVST,{active:['Active','live'],live:['Live now','live'],upcoming:['Upcoming','info'],completed:['Completed','teal'],done:['All done','done'],void:['Void','bad']});

/* ---------- function icon and a ready-made cover when no photo is uploaded ---------- */
function typeIc(t){t=String(t||'').toLowerCase();return /birth/.test(t)?'cake':/recep/.test(t)?'reception':/engag|nichay/.test(t)?'engagement':/wedd|kalyan|marri/.test(t)?'wedding':/valaik|seemant|baby show|bangle/.test(t)?'bangles':/ear|kaathu|karna/.test(t)?'ear':/puberty|manjal|ritu/.test(t)?'lotus':/griha|house|grah/.test(t)?'house':/nam|thottil|cradle/.test(t)?'baby':/60|sixty|shashti|mani|80/.test(t)?'sixty':/temple|kovil|kumbab|festival/.test(t)?'temple':'sparkle'}
const CVPAL=[['#211B6E','#4C41DA','#8E84FF'],['#2A1F7A','#5B3FD6','#B49CFF'],['#1C2370','#3A50D9','#8FA3FF'],['#2B1A66','#6A3FC9','#C9A6FF']];
function autoArt(ev,mini){const pal=CVPAL[[...String(ev.type||ev.name)].reduce((a,c)=>a+c.charCodeAt(0),0)%CVPAL.length],k=typeIc(ev.type);
  if(mini)return `<span class="cv-auto mini" style="--a:${pal[0]};--b:${pal[1]};--c:${pal[2]}">${wic(k,20)}</span>`;
  return `<span class="cv-auto" style="--a:${pal[0]};--b:${pal[1]};--c:${pal[2]}"><span class="cva-ring"></span><span class="cva-ic">${wic(k,34)}</span><span class="cva-t"><b>${esc(ev.name)}</b><small>${esc(ev.type||'')}${ev.date?' · '+dfmt(ev.date):''}</small></span><span class="cva-mark">${mpMark()}</span></span>`}

/* ---------- one master record: also the Master Admin guest database and logins ---------- */
let _mxg=null,_mxgAt=0;
function mxGuests(){if(_mxg&&Date.now()-_mxgAt<60000)return _mxg;try{_mxg=new Map();(MX.data().guests||[]).forEach(g=>{if(g.mobile&&!_mxg.has(g.mobile))_mxg.set(g.mobile,g)});_mxgAt=Date.now()}catch(e){_mxg=new Map()}return _mxg}
function masterFind(mob){mob=normMob(mob||'');if(!mobOk(mob))return null;const p=pplGet(mob);if(p)return p;
  const g=mxGuests().get(mob);if(g)return {mobile:mob,name:g.name,place:g.city||'',des:g.des||'',address:'',at:0,srcs:['master'],accs:[]};
  const u=S.users.find(x=>x.mobile===mob&&x.role!=='platform');if(u){const A=accById(u.acc)||{};return {mobile:mob,name:u.name,place:A.city||'',des:'',address:'',at:0,srcs:['user'],accs:[]}}return null}
const pplSrcTxt2=p=>(p.srcs||[]).includes('master')?'the Master Admin guest database':(p.srcs||[]).includes('user')?'Moi Point logins':pplSrcTxt(p);
let _mxPlaces=null;
function masterPlaces(){if(_mxPlaces)return _mxPlaces;const c={};mxGuests().forEach(g=>{if(g.city)c[g.city]=(c[g.city]||0)+1});Object.values(S.people||{}).forEach(p=>{if(p.place)c[p.place]=(c[p.place]||0)+3});_mxPlaces=Object.entries(c).sort((a,b)=>b[1]-a[1]).map(x=>x[0]);setTimeout(()=>{_mxPlaces=null},30000);return _mxPlaces}
const masterDes=()=>{const c={};Object.values(S.people||{}).forEach(p=>{if(p.des)c[p.des]=(c[p.des]||0)+1});return Object.entries(c).sort((a,b)=>b[1]-a[1]).map(x=>x[0])};
const OTHK={ctype:'ctypes',crel:'crels',xcat:'xcats'},OTHB={ctype:()=>TYPES,crel:()=>RELS,xcat:()=>XCATS};
function otherList(kind){const M=P()[OTHK[kind]]||{};return [...Object.entries(M).sort((a,b)=>b[1]-a[1]).map(x=>x[0]),...OTHB[kind]().filter(x=>x!=='Other')]}
function xcatsFor(A,cur){const own=(A&&A.xcats)||[];const L=[...XCATS.filter(t=>t!=='Other'),...own.filter(t=>!XCATS.includes(t))];if(cur&&!L.includes(cur)&&cur!=='Other')L.push(cur);return [...L,'Other']}

/* ---------- what each helper may do in an event ---------- */
const PKINDS=[['k_cash','Cash'],['k_gold','Gold'],['k_silver','Silver'],['k_gift','Gift items'],['k_other','Other items']];
const PACTS=[['list','See the Moi List'],['edit','Edit entries'],['void','Void / Delete entries'],['exp','Add expenses'],['pay','Add payouts'],['verify','Verify payments'],['rep','See reports'],['out','Export / download']];
function permDef(role){const all=Object.fromEntries(PKINDS.map(x=>[x[0],1]));return role==='manager'?{...all,list:1,edit:1,void:1,exp:1,pay:1,verify:1,rep:1,out:0}:{...all,list:1,edit:0,void:0,exp:0,pay:1,verify:0,rep:0,out:0}}
function permOf(eid){const r=roleIn(eid);if(!r)return {};if(r==='admin'){const o=permDef('manager');Object.keys(o).forEach(k=>o[k]=1);return o}const a=S.eventUsers.find(x=>x.event_id===eid&&x.user_id===me.id);return {...permDef(r),...((a&&a.perm)||{})}}
function permFields(px,role,perm){const p={...permDef(role||'collector'),...(perm||{})};const box=(k,l)=>`<label class="pchip"><input type="checkbox" id="${px}_p_${k}" ${p[k]?'checked':''}><span>${l}</span></label>`;
  return `<fieldset class="field full perm-f" data-permpx="${px}"><span>${ic('shield',15)} What they can collect</span><div class="pchips">${PKINDS.map(([k,l])=>box(k,l)).join('')}</div><span>${ic('sliders',15)} What they can do</span><div class="pchips">${PACTS.map(([k,l])=>box(k,l)).join('')}</div><small class="muted">Receiving Moi is always allowed. Change these any time from Staff &amp; Access.</small></fieldset>`}
function readPerm(f,px){const o={};let any=false;[...PKINDS,...PACTS].forEach(([k])=>{const el=f.querySelector('#'+px+'_p_'+k);if(el){any=true;o[k]=el.checked?1:0}});return any?o:null}
const permTxt=a=>{const p={...permDef(a.role),...(a.perm||{})};const ks=PKINDS.filter(([k])=>p[k]).map(x=>x[1]);return (ks.length===PKINDS.length?'All Moi types':ks.join(', ')||'No Moi types')+(p.edit?' · edit':'')+(p.void?' · void':'')+(p.out?' · export':'')};
function kindsAllowed(ev,f){const p=permOf(ev.id),L=KIND.filter(k=>p['k_'+k]!==0);if(!L.length)return ['cash'];if(!L.includes(f.kind)){f.kind=L[0]}return L}
const PERMGATE={moiEdit:['edit','Editing entries'],moiDel:['void','Voiding entries'],bkOpen:['out','Exporting the Moi Book'],bkPrint:['out','Exporting the Moi Book'],copyCsv:['out','Exporting'],repPrint:['out','Exporting reports'],repCsv:['out','Exporting reports'],expNew:['exp','Adding expenses'],poNew:['pay','Adding payouts'],verify:['verify','Verifying payments'],reject:['verify','Verifying payments']};
Object.entries(PERMGATE).forEach(([k,[pk,lbl]])=>{const f=ACT[k];if(!f)return;ACT[k]=(b,e)=>{const ev=curEv||(b&&b.dataset&&b.dataset.id&&S.moi.find(m=>m.id===b.dataset.id)&&S.events.find(x=>x.id===S.moi.find(m=>m.id===b.dataset.id).event_id));if(ev&&me&&me.role!=='admin'&&!permOf(ev.id)[pk])return toast(`${lbl} is not allowed for your login. Ask the event owner.`,'bad');return f(b,e)}});
document.addEventListener('change',e=>{const t=e.target;if(t.tagName!=='SELECT'||!t.id)return;const m=t.id.match(/^(u|ue\w+?|t)_?role(\d*)$/)||t.id.match(/^(ue\w+)_role$/);if(!m)return;const px=t.id==='u_role'?'u':/^t_role\d+$/.test(t.id)?'t'+t.id.slice(6):t.id.replace(/_role$/,'');const d=permDef(t.value);Object.entries(d).forEach(([k,v])=>{const el=document.getElementById(px+'_p_'+k);if(el)el.checked=!!v})});

/* ---------- filters: one line, and the chosen ones stand out ---------- */
const FSEL='.filters,.xfilters,.fbar-top';
function fDefault(el){if(el.dataset.fdef!==undefined)return el.dataset.fdef;let d='';if(el.tagName==='SELECT')d=el.options.length?el.options[0].value:'';el.dataset.fdef=d;return d}
function fLabel(el){const a=el.getAttribute('aria-label');if(a)return a.replace(/^Search.*$/,'Search');const l=el.closest('label');if(l){const t=[...l.childNodes].filter(n=>n.nodeType===3).map(n=>n.nodeValue.trim()).join(' ').trim();if(t)return t}return el.placeholder?'Search':'Filter'}
function fDecor(){document.querySelectorAll(FSEL).forEach(box=>{if(box.closest('.vid'))return;const els=[...box.querySelectorAll('select,input')].filter(x=>!['checkbox','radio','hidden','button'].includes(x.type));const on=[];
  els.forEach(el=>{const d=fDefault(el),v=el.value,act=v!==d&&!(el.tagName==='SELECT'&&/sort/i.test((el.dataset.lq||el.dataset.rq||el.id||'')+(el.getAttribute('aria-label')||'')));el.classList.toggle('f-on',v!==d);if(act)on.push([el,el.tagName==='SELECT'?(el.options[el.selectedIndex]||{}).text:v])});
  let sum=box.nextElementSibling;if(!sum||!sum.classList.contains('f-sum')){if(!on.length)return;sum=document.createElement('div');sum.className='f-sum';box.after(sum)}
  sum.hidden=!on.length;const html=on.length?`<span class="fs-l">${ic('sliders',14)} Showing only</span>${on.map(([el,t],i)=>`<button type="button" class="fs-chip" data-fsi="${i}"><b>${esc(fLabel(el))}:</b> ${esc(t)} <i aria-hidden="true">✕</i></button>`).join('')}<button type="button" class="fs-clr" data-fsi="all">Clear all</button>`:'';if(sum._h!==html){sum._h=html;sum.innerHTML=html}sum._els=on.map(x=>x[0])})}
function fKey(el){if(el.id)return '#'+CSS.escape(el.id);for(const a of el.attributes){if(a.name.startsWith('data-')&&a.name!=='data-fdef')return `[${a.name}="${CSS.escape(a.value)}"]`}return null}
function fResetAll(els){const keys=els.map(el=>[fKey(el),fDefault(el)]);keys.forEach(([k,d])=>{const el=k&&document.querySelector(k);if(!el)return;el.value=d;el.dataset.fdef=d;['input','change'].forEach(ev=>el.dispatchEvent(new Event(ev,{bubbles:true})))})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-fsi]');if(!b)return;const sum=b.closest('.f-sum');if(!sum||!sum._els)return;e.preventDefault();e.stopPropagation();const els=sum._els;fResetAll(b.dataset.fsi==='all'?els:[els[+b.dataset.fsi]].filter(Boolean));setTimeout(fDecor,60)},true);
let _fdq=0;const fdObs=new MutationObserver(()=>{if(_fdq)return;_fdq=requestAnimationFrame(()=>{_fdq=0;try{fDecor()}catch(_){}})});fdObs.observe(document.body,{childList:true,subtree:true});
document.addEventListener('change',()=>setTimeout(fDecor,30));document.addEventListener('input',e=>{if(e.target.closest&&e.target.closest(FSEL))setTimeout(fDecor,30)});

/* ---------- Moi List: special guests at the top, drag to reorder ---------- */
const STAR='<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true"><path d="m12 2.8 2.8 5.8 6.3.9-4.6 4.4 1.1 6.3L12 17.2l-5.6 3 1.1-6.3L2.9 9.5l6.3-.9z"/></svg>';
const vipTag=()=>`<span class="tag vip">${STAR}Special guest</span>`;
const dragH=()=>`<span class="pin-drag" title="Drag to change the order" aria-label="Drag to change the order" role="button" tabindex="-1"><svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><circle cx="9" cy="6" r="1.6"/><circle cx="15" cy="6" r="1.6"/><circle cx="9" cy="12" r="1.6"/><circle cx="15" cy="12" r="1.6"/><circle cx="9" cy="18" r="1.6"/><circle cx="15" cy="18" r="1.6"/></svg></span>`;
let pdrag=null;
document.addEventListener('pointerdown',e=>{const h=e.target.closest('.pin-drag');if(!h)return;const row=h.closest('[data-pin]');if(!row)return;e.preventDefault();e.stopPropagation();
  pdrag={row,box:row.parentElement,moved:false,y0:e.clientY};row.classList.add('dragging');try{h.setPointerCapture(e.pointerId)}catch(_){}},true);
document.addEventListener('pointermove',e=>{if(!pdrag)return;e.preventDefault();const rows=[...pdrag.box.querySelectorAll(':scope>[data-pin]')];for(const r of rows){if(r===pdrag.row)continue;const b=r.getBoundingClientRect();if(e.clientY>b.top&&e.clientY<b.bottom){const after=e.clientY>b.top+b.height/2;if(after&&r.nextElementSibling!==pdrag.row)r.after(pdrag.row);else if(!after&&r.previousElementSibling!==pdrag.row)r.before(pdrag.row);pdrag.moved=true;break}}},{passive:false});
document.addEventListener('pointerup',()=>{if(!pdrag)return;const d=pdrag;pdrag=null;d.row.classList.remove('dragging');if(!d.moved)return;const ev=curEv;if(!ev)return;const order=[...d.box.querySelectorAll(':scope>[data-pin]')].map(r=>r.dataset.pin);ev.pins=order;log(ev.id,'Special guests reordered',order.length+' entries');save();setTimeout(render,0)});
document.addEventListener('click',e=>{if(e.target.closest('.pin-drag')){e.preventDefault();e.stopPropagation()}},true);

/* ---------- Event report: the whole function on one page, to print, save as PDF or share ---------- */
function repStats(ev){const t=calc(ev.id),ms=S.moi.filter(m=>m.event_id===ev.id),ok=ms.filter(OK),cash=ok.filter(m=>!isItem(m));
  const items={gold:0,silver:0,gift:0,other:0};ok.filter(isItem).forEach(m=>{items[m.kind]=(items[m.kind]||0)+1});
  const rel={};cash.forEach(m=>{const r=m.c.relationship||'Other';rel[r]=(rel[r]||0)+(+m.amount||0)});
  const by={};ok.forEach(m=>{const n=uname(m.collected_by);by[n]=by[n]||{n:0,amt:0};by[n].n++;if(!isItem(m))by[n].amt+=+m.amount||0});
  const xs=S.expenses.filter(x=>x.event_id===ev.id),cats={};xs.forEach(x=>cats[x.category]=(cats[x.category]||0)+(+x.amount||0));
  const pos=(S.payouts||[]).filter(x=>x.event_id===ev.id);
  const top=cash.slice().sort((a,b)=>b.amount-a.amount).slice(0,10),voids=ms.filter(m=>m.status==='void').length;
  return {t,ms,ok,cash,items,rel,by,xs,cats,pos,top,voids}}
function repSummary(ev){const R=repStats(ev),t=R.t,inT=t.total,outT=t.expenses+t.payouts,mx=Math.max(1,inT,outT),P=permOf(ev.id),tot=(t.cash+t.upi+t.online)||1;
  const bar=(l,v,c)=>`<div class="rs-bar"><span>${l}</span><div><i style="width:${Math.max(2,v/mx*100)}%;background:${c}"></i></div><b>${fmt(v)}</b></div>`;
  const kv=(o,f)=>Object.entries(o).sort((a,b)=>b[1]-a[1]);
  return `<section class="rs" id="repSum">${rsBrand(ev)}<div class="rs-head"><div class="rs-ev">${evLogo(ev)}<div><p class="eyebrow">Event / Function report</p><h2>${esc(ev.name)}</h2><p class="muted small">${esc(ev.type)} · ${esc(ev.no||'')} · ${dfmt(ev.date)} · ${tfmt(ev.start)}–${tfmt(ev.end)} · ${esc(ev.venue||'')}</p></div></div>
   <div class="rs-acts">${P.out?`<button class="btn btn-primary btn-sm" data-act="repPrint">${ic('bill',16)}Print / Save PDF</button><button class="btn btn-ghost btn-sm" data-act="repHtml">${ic('upload',16)}Download report</button><button class="btn btn-ghost btn-sm" data-act="repCsv">${ic('upload',16)}Download CSV</button><button class="btn btn-ghost btn-sm" data-act="repWa">${ic('msg',16)}Share summary</button>`:`<span class="small muted">${ic('lock',14)} Export is turned off for your login</span>`}</div></div>
   <div class="rs-kpis"><div class="k in"><span>Moi received</span><b>${fmt(t.total)}</b><small>${t.okN} entries${t.pendingN?` · ${t.pendingN} pending`:''}</small></div><div class="k out"><span>Spent</span><b>${fmt(outT)}</b><small>${fmt(t.expenses)} expenses · ${fmt(t.payouts)} payouts</small></div><div class="k bal"><span>Balance in hand</span><b>${fmt(t.net)}</b><small>Moi − expenses − payouts${t.gwFees?' − fees':''}</small></div><div class="k items"><span>Gold, silver &amp; gifts</span><b>${t.goldG?(+t.goldG).toFixed(2)+' g':'—'}</b><small>${R.items.gold} gold · ${R.items.silver} silver · ${R.items.gift+R.items.other} gifts</small></div></div>
   <div class="rs-grid"><div class="rs-card"><h3>Money in and out</h3>${bar('Moi received',inT,'linear-gradient(90deg,#0F9D58,#33C47A)')}${bar('Expenses',t.expenses,'#E5484D')}${bar('Payouts',t.payouts,'#F59E0B')}${bar('Balance',Math.max(0,t.net),'linear-gradient(90deg,#28227A,#5A52E0)')}</div>
    <div class="rs-card"><h3>How Moi came in</h3><div class="rs-split"><i style="flex:${t.cash||0};background:#0F9D58" title="Cash"></i><i style="flex:${t.upi||0};background:#2563EB" title="UPI"></i><i style="flex:${t.online||0};background:#7C3AED" title="Online"></i></div>
     <dl class="rs-dl"><div><dt><i style="background:#0F9D58"></i>Cash</dt><dd>${fmt(t.cash)} · ${Math.round(t.cash/tot*100)}%</dd></div><div><dt><i style="background:#2563EB"></i>Offline UPI</dt><dd>${fmt(t.upi)} · ${Math.round(t.upi/tot*100)}%</dd></div><div><dt><i style="background:#7C3AED"></i>Online</dt><dd>${fmt(t.online)} · ${Math.round(t.online/tot*100)}%</dd></div>${t.gwFees?`<div><dt>Gateway fees</dt><dd>− ${fmt2(t.gwFees)}</dd></div>`:''}<div><dt>Cash at the counter now</dt><dd>${fmt(t.cashAtCounter)}</dd></div>${t.returns?`<div><dt>Moi we returned (${t.returnedN})</dt><dd>${fmt(t.returns)}</dd></div>`:''}</dl></div>
    <div class="rs-card"><h3>Top 10 contributors</h3>${R.top.length?`<ol class="rs-top">${R.top.map(m=>`<li><span><b>${esc(UN(m.c.name))}</b><small>${esc(m.c.relationship||'')}${m.c.place?' · '+esc(UP(m.c.place)):''}</small></span><b>${fmt(m.amount)}</b></li>`).join('')}</ol>`:'<p class="muted small">No Moi yet.</p>'}</div>
    <div class="rs-card"><h3>By relationship</h3>${kv(R.rel).slice(0,8).map(([k,v])=>`<div class="rs-row"><span>${esc(k)}</span><b>${fmt(v)}</b></div>`).join('')||'<p class="muted small">—</p>'}</div><div class="rs-card"><h3>Expenses by category</h3>${kv(R.cats).map(([k,v])=>`<div class="rs-row"><span>${esc(k)}</span><b>${fmt(v)}</b></div>`).join('')||'<p class="muted small">No expenses.</p>'}</div>
    <div class="rs-card"><h3>Payouts</h3>${R.pos.length?R.pos.map(p=>`<div class="rs-row"><span>${esc(p.to||'')}<small>${esc(p.purpose||'')} · ${dfmt(p.date)}</small></span><b>${fmt(p.amount)}</b></div>`).join(''):'<p class="muted small">No payouts.</p>'}</div><div class="rs-card"><h3>Collected by</h3>${Object.entries(R.by).sort((a,b)=>b[1].amt-a[1].amt).map(([k,v])=>`<div class="rs-row"><span>${esc(k)}<small>${v.n} entries</small></span><b>${fmt(v.amt)}</b></div>`).join('')||'<p class="muted small">—</p>'}</div></div>
   <p class="small muted rs-foot">Made by Moi Point on ${new Date().toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'})}${R.voids?` · ${R.voids} void entries left out`:''}.</p></section>`}
function repText(ev){const R=repStats(ev),t=R.t;return `${ev.name} · ${dfmt(ev.date)}\nMoi received: ${fmt(t.total)} (${t.okN} entries)\nExpenses: ${fmt(t.expenses)}\nPayouts: ${fmt(t.payouts)}\nBalance in hand: ${fmt(t.net)}\nCash ${fmt(t.cash)} · UPI ${fmt(t.upi)} · Online ${fmt(t.online)}\n— Moi Point`}
function repCsvText(ev){const R=repStats(ev),t=R.t,q=c=>/[",\n]/.test(String(c))?'"'+String(c).replace(/"/g,'""')+'"':c,rows=[['Event / Function report',ev.name],['Date',dfmt(ev.date)],['Venue',ev.venue||''],[],['Item','Amount'],['Moi received',t.total],['Cash',t.cash],['Offline UPI',t.upi],['Online',t.online],['Expenses',t.expenses],['Payouts',t.payouts],['Balance in hand',t.net],[],['Receipt','Name','Relationship','Place','Amount / item','Mode','Date','Status']];
  R.ms.forEach(m=>rows.push([m.code,m.c.name,m.c.relationship||'',m.c.place||'',amtTxt(m),MODE[m.mode]||m.mode,m.date,STATUS[m.status]?STATUS[m.status][0]:m.status]));rows.push([],['Expense','Category','Amount','Date']);R.xs.forEach(x=>rows.push([x.desc,x.category,x.amount,x.date]));
  return rows.map(r=>r.map(q).join(',')).join('\n')}
function dlFile(name,text,type){try{const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);return true}catch(e){return false}}
Object.assign(ACT,{
 repPrint:()=>{const ev=curEv;if(!ev)return;let pa=$('#printArea');if(!pa){pa=document.createElement('div');pa.id='printArea';document.body.appendChild(pa)}pa.innerHTML=`<div class="rs-print">${repSummary(ev)}</div>`;let ps=$('#printPage');if(!ps){ps=document.createElement('style');ps.id='printPage';document.head.appendChild(ps)}ps.textContent='@page{size:A4 portrait;margin:10mm}';log(ev.id,'Event report exported','PDF');save();if(framed){toast('Printing is blocked in this preview. It works in the live app.','bad');return}setTimeout(()=>{try{window.print()}catch(e){}},150)},
 repCsv:()=>{const ev=curEv;if(!ev)return;const txt=repCsvText(ev);log(ev.id,'Event report exported','CSV');save();if(framed||!dlFile(`EventReport-${String(ev.no||ev.id).replace(/\W/g,'')}.csv`,txt,'text/csv')){copy(txt,'Report CSV');return}toast('Report CSV downloaded','good')},
 repWa:()=>{const ev=curEv;if(!ev)return;const t=repText(ev);copy(t,'Summary');try{window.open('https://wa.me/?text='+encodeURIComponent(t),'_blank','noopener')}catch(_){}},
 repOpen:b=>{ui.rep='sum';go('ev-'+(b.dataset.id||curEv.id)+'-reports')}});
const repCard=ev=>can(ev.id,'reports')?`<section class="rep-cta"><span class="rc-ic">${ic('chart',22)}</span><div><b>Event / Function report</b><small>Moi in, money out and balance on one page. Print, save as PDF or share.</small></div><button class="btn btn-primary btn-sm" data-act="repOpen" data-id="${ev.id}">Open report ${ic('arrow',16)}</button></section>`:'';

/* ---------- receipt QR: what a guest sees after scanning it ---------- */
function vVerify(code){code=decodeURIComponent(String(code||'')).trim();const m=S.moi.find(x=>String(x.code).toLowerCase()===code.toLowerCase()),ev=m&&S.events.find(e=>e.id===m.event_id);
  const top=`<header class="vf-top">${logo()}<span class="bw"><span class="bw-n">${MPW()}</span><small class="tagl">Grow Together</small></span><span class="vf-k">Receipt check</span></header>`;
  if(!m||!ev)return `<div class="vf">${top}<section class="vf-card bad"><span class="vf-ic">${ic('alert',34)}</span><h1>We couldn’t find this receipt</h1><p>The number <b class="code">${esc(code||'—')}</b> is not on Moi Point. The receipt may be typed wrongly, or it may not be a real Moi Point receipt.</p><p class="small muted">Check with the family who gave it. Real receipts always open this page with the full details.</p><button class="btn btn-ghost" data-go="#home">Go to Moi Point</button></section></div>`;
  const ST={received:['good','Genuine receipt · Moi received','The family has received this Moi and recorded it in their Moi book.'],verified:['good','Genuine receipt · payment checked','The family checked this payment and recorded it in their Moi book.'],pending:['warn','Real receipt · payment being checked','The family has not yet checked this UPI payment. It becomes final after they verify it.'],tocollect:['warn','Not complete · pay at the counter','This entry waits for the cash to be paid at the Moi counter.'],rejected:['bad','Payment not accepted','The family could not find this payment. Please talk to them.'],void:['bad','Cancelled receipt · not valid','This receipt was cancelled by the family. It is not counted.']},s=ST[m.status]||ST.received;
  const row=(k,v)=>v?`<div><dt>${k}</dt><dd>${v}</dd></div>`:'';
  return `<div class="vf">${top}<section class="vf-card ${s[0]}"><span class="vf-ic">${ic(s[0]==='good'?'check':s[0]==='warn'?'clock':'x',34)}</span><h1>${s[1]}</h1><p>${s[2]}</p><div class="vf-amt">${esc(amtTxt(m))}</div><p class="vf-no">Receipt <b class="code">${esc(m.code)}</b></p></section>
   <section class="vf-sec"><div class="vf-ev">${evLogo(ev)}<div><b>${esc(ev.name)}</b><small>${esc(ev.type)} · ${dfmt(ev.date)} · ${esc(ev.venue||'')}</small></div></div>
    <dl class="kvlist">${row('Given by',esc(m.c.name))}${row('Relationship',esc(m.c.relationship||''))}${row('Place',esc(m.c.place||''))}${row('Mobile',m.c.mobile?esc(maskMob(m.c.mobile)):'')}${row('Paid by',esc(MODE[m.mode]||m.mode))}${row('Date and time',`${dfmt(m.date)}${m.time?', '+tfmt(m.time):''}`)}${row('Recorded by',esc(uname(m.collected_by)))}${row('Organiser',esc(ev.organizer||''))}</dl></section>
   <section class="vf-sec vf-why"><h2>${ic('qr',18)} Why is there a QR on the receipt?</h2><ul><li><b>To prove it is real.</b> Scanning opens this page from Moi Point, so nobody can make or change a receipt by hand.</li><li><b>To keep your record.</b> It shows what you gave, to which function, and when — handy when you attend their next function.</li><li><b>To check the status.</b> UPI and cash entries show whether the family has confirmed them.</li></ul></section>
   <p class="small muted center">Moi Point never shows the full mobile number on this page.</p><div class="btn-row" style="justify-content:center;margin-bottom:24px"><button class="btn btn-ghost" data-go="#home">${ic('home',16)}About Moi Point</button></div></div>`}

/* ---------- a QR-like drawing that works offline (for illustrations) ---------- */
function qrArt(seed,size){let s=0;for(const c of String(seed))s=(s*31+c.charCodeAt(0))>>>0;const r=()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296},n=25,c=[];
  const fin=(x,y)=>`<rect x="${x}" y="${y}" width="7" height="7" fill="#1D1A4A"/><rect x="${x+1}" y="${y+1}" width="5" height="5" fill="#fff"/><rect x="${x+2}" y="${y+2}" width="3" height="3" fill="#1D1A4A"/>`;
  for(let y=0;y<n;y++)for(let x=0;x<n;x++){if((x<8&&y<8)||(x>16&&y<8)||(x<8&&y>16))continue;if(r()>.52)c.push(`<rect x="${x}" y="${y}" width="1" height="1"/>`)}
  return `<svg viewBox="-1 -1 27 27" width="${size||120}" height="${size||120}" shape-rendering="crispEdges" aria-hidden="true"><rect x="-1" y="-1" width="27" height="27" fill="#fff"/><g fill="#1D1A4A">${c.join('')}</g>${fin(0,0)}${fin(18,0)}${fin(0,18)}</svg>`}
/* website slide: guest scans the counter QR with a phone and pays */
function lScanArt(){return `<div class="ls-art scan"><span class="ls-blob"></span><div class="sc-stand"><div class="sc-board"><span class="sc-k">Scan to give Moi</span><b>Arun &amp; Priya Wedding</b><div class="sc-qr">${qrArt('EV002',150)}</div><small>Cash · UPI · Online</small><span class="sc-brand">${mpMark()} Moi Point</span></div><i class="sc-leg"></i></div>
  <div class="sc-phone"><div class="sc-scr"><div class="sc-cam"><div class="sc-qr2">${qrArt('EV002',120)}</div><i class="sc-c tl"></i><i class="sc-c tr"></i><i class="sc-c bl"></i><i class="sc-c br"></i><i class="sc-line"></i><span class="sc-hint">Point at the QR</span></div>
   <div class="sc-pay"><p class="sc-ev">Arun &amp; Priya Wedding</p><div class="sc-f"><span>Name</span><b>Murugesan</b></div><div class="sc-f"><span>Mobile</span><b>98400 •• •01 ✓</b></div><div class="sc-amt">₹1,001</div><div class="sc-mode"><span class="on">Online</span><span>UPI</span><span>Cash</span></div><button class="sc-btn">Pay ₹1,001</button></div>
   <div class="sc-done"><span class="sc-tick">${ic('check',30)}</span><b>Moi received</b><small>₹1,001 · EV002/016</small><small>Receipt sent on WhatsApp</small></div></div></div></div>`}

