const lVidCard=()=>`<div class="lp-vcard" id="lpVcard"><button class="lp-vthumb" data-act="vidWeb" aria-label="Play: how Moi Point works">${SHOTS&&SHOTS['desk-dash']?`<img src="${SHOTS['desk-dash']}" alt="">`:''}<i>${VPLAY}</i><em>${vfmt(VTOT())}</em></button><div class="lp-vtxt"><span class="lp-chip">${ic('video',14)} 1½-minute video</span><h3>See how Moi Point works</h3><p>Create a function, receive Moi at the counter and by QR, send receipts, add expenses and close the accounts — step by step.</p><button class="btn btn-primary" data-act="vidWeb">${VPLAY.replace(/20/g,'16')}Play video</button></div></div>`;
