/* ---------- offline UPI accounts and the bank account, each in its own small pop-up ---------- */
function upiList(px){const el=document.getElementById(px+'upisJson');try{return el?JSON.parse(el.value||'[]'):[]}catch(e){return []}}
function upiSave(px,L){const el=document.getElementById(px+'upisJson');if(el)el.value=JSON.stringify(L);const box=document.getElementById(px+'upiSum');if(box)box.innerHTML=upiSumHtml(px,L)}
function upiSumHtml(px,L){return L.length?L.map((a,i)=>`<div class="upi-row ${a.on===false?'off':''}"><span class="ur-qr">${a.qr?`<img src="${a.qr}" alt="">`:ic('qr',20)}</span><div class="ur-t"><b>${esc(a.id||'QR image only')}</b><small>${esc(a.name||'—')}${a.on===false?' · not used now':' · in use'}</small></div><label class="pmx-sw" title="Use this account"><input type="checkbox" data-upion="${px}" data-i="${i}" ${a.on===false?'':'checked'}><span class="sw" aria-hidden="true"></span></label><button type="button" class="icon-btn icon-sm" data-act="upiEdit" data-px="${px}" data-i="${i}" aria-label="Edit">${ic('edit',16)}</button><button type="button" class="icon-btn icon-sm" data-act="upiRm" data-px="${px}" data-i="${i}" aria-label="Remove">${ic('trash',16)}</button></div>`).join(''):`<p class="small muted">No UPI account yet.</p>`}
function upiBox(e,px){const accs=(e.upis&&e.upis.length?e.upis:(e.upi?[{id:e.upi,name:e.payee||''}]:[])).map(a=>({id:a.id||'',name:a.name||'',qr:a.qr||null,on:a.on!==false}));
  return `<input type="hidden" id="${px}upisJson" value="${esc(JSON.stringify(accs))}"><div class="upi-sum" id="${px}upiSum">${upiSumHtml(px,accs)}</div><button type="button" class="btn btn-soft btn-sm" data-act="upiEdit" data-px="${px}" data-i="-1">${ic('plus',16)}Add a UPI account</button><p class="small muted">Add as many as you like. Switch on the ones to use now; the counter moves to the next one when a bank’s daily limit is close.</p>`}
function bankLinked(px){const ok=document.getElementById(px+'bk_ok');return !!(ok&&ok.checked)}
function bankBox(e,px){const b=e.bank&&e.bank.linked?e.bank:null;
  return `<div class="bank-box"><span class="lbl">Bank account for online Moi</span><div id="${px}bkSum" class="bk-sum">${b?`<div class="upi-row"><span class="ur-qr">${ic('card',20)}</span><div class="ur-t"><b>${esc(b.holder)} · ••••${esc(b.last4)}</b><small>${esc(b.ifsc)} · linked</small></div></div>`:`<p class="small muted">${ic('alert',14)} Not added yet. Online Moi starts once you add it.</p>`}</div>
   <div hidden><input id="${px}bk_name" value="${esc(b?b.holder:'')}"><input id="${px}bk_no" value=""><input id="${px}bk_ifsc" value="${esc(b?b.ifsc:'')}"><input type="checkbox" id="${px}bk_ok" ${b?'checked':''}></div>
   <button type="button" class="btn btn-soft btn-sm" id="${px}bkBtn" data-act="bankEdit" data-px="${px}">${ic(b?'edit':'plus',16)}${b?'Change bank account':'Add bank account'}</button></div>`}
function subPop(html){subClose();const o=document.createElement('div');o.className='subpop';o.id='subpop';o.innerHTML=`<div class="sp-card" role="dialog" aria-modal="true">${html}</div>`;document.body.appendChild(o);setTimeout(()=>{const i=o.querySelector('input:not([type=hidden]):not([type=checkbox])');if(i)i.focus()},40);return o}
function subClose(){const o=document.getElementById('subpop');if(o)o.remove()}
function bankPop(px,fromToggle){const v=id=>(document.getElementById(px+id)||{}).value||'';subPop(`<div class="sp-h"><div><h3>${ic('card',20)} Bank account for online Moi</h3><p class="small muted">Online Moi is settled to this account, usually the next working day.</p></div></div>
  <div class="fields"><label class="field full"><span>Account holder name <i>*</i></span><input id="sp_bk_name" value="${esc(v('bk_name'))}" autocomplete="off"></label><label class="field"><span>Account number <i>*</i></span><input id="sp_bk_no" inputmode="numeric" autocomplete="off" placeholder="9 to 18 digits"></label><label class="field"><span>Type the number again <i>*</i></span><input id="sp_bk_no2" inputmode="numeric" autocomplete="off"></label><label class="field full"><span>IFSC code <i>*</i></span><input id="sp_bk_ifsc" value="${esc(v('bk_ifsc'))}" autocapitalize="characters" placeholder="e.g. SBIN0001234"></label>
  <label class="check full"><input type="checkbox" id="sp_bk_ok"> I confirm this account belongs to the family or the organiser.</label><p class="sp-err full" id="sp_err" hidden></p></div>
  <div class="sp-f"><button type="button" class="btn btn-ghost" data-act="spCancel" data-px="${px}" data-k="${fromToggle?'online':''}">Cancel</button><button type="button" class="btn btn-primary" data-act="bankSave" data-px="${px}">${ic('check',16)}Save bank account</button></div>`)}
const UPI_RE=/^[\w.\-]{2,}@[a-z][a-z0-9]+$/i;
function upiLive(){const box=document.getElementById('sp_qrprev');if(!box)return;const id=document.getElementById('sp_upi').value.trim().replace(/\s/g,''),nm=document.getElementById('sp_upn').value.trim();
  if(!UPI_RE.test(id)){box.className='full upi-auto';box.innerHTML=`<span class="upi-auto-e">${ic('qr',22)}</span><small class="muted">Type the UPI ID and the QR appears here</small>`;return}
  box.className='full upi-auto on';box.innerHTML=`<div class="qr-box" data-qr="${esc(upiStr({name:(curEv&&curEv.name)||'Moi Point'},0,'',{id,name:nm||id}))}" data-size="150"></div><div class="upi-auto-t"><b>${ic('check',15)}QR created from this UPI ID</b><small class="muted">Scan it with any UPI app and check the name. No need to pay.</small></div>`;mountQR(box)}
function upiPop(px,i,fromToggle){const L=upiList(px),a=i>=0?L[i]:{id:'',name:'',qr:null,on:true};subPop(`<div class="sp-h"><div><h3>${ic('phone',20)} ${i>=0?'Edit UPI account':'Add a UPI account'}</h3><p class="small muted">Type your UPI ID and the QR is created by itself. Guests scan it, pay and upload a screenshot; you verify it.</p></div></div>
  <div class="fields"><label class="field full"><span>UPI ID <i>*</i></span><input id="sp_upi" value="${esc(a.id)}" placeholder="name@okaxis" autocapitalize="none" autocomplete="off"></label><label class="field full"><span>Account holder name</span><input id="sp_upn" value="${esc(a.name)}" placeholder="e.g. Ramesh Kumar"></label>
  <div class="full upi-auto" id="sp_qrprev" aria-live="polite"></div>
  <label class="check full"><input type="checkbox" id="sp_upion" ${a.on===false?'':'checked'}> Use this account now</label><p class="sp-err full" id="sp_err" hidden></p></div>
  <div class="sp-f"><button type="button" class="btn btn-ghost" data-act="spCancel" data-px="${px}" data-k="${fromToggle?'upi':''}">Cancel</button><button type="button" class="btn btn-primary" data-act="upiSaveB" data-px="${px}" data-i="${i}">${ic('check',16)}Save UPI account</button></div>`);
  ['sp_upi','sp_upn'].forEach(id=>document.getElementById(id).addEventListener('input',upiLive));upiLive()}
const spErr=t=>{const e=document.getElementById('sp_err');if(e){e.hidden=false;e.textContent=t}};
Object.assign(ACT,{
 bankEdit:b=>bankPop(b.dataset.px,false),upiEdit:b=>upiPop(b.dataset.px,+b.dataset.i,false),
 upiRm:b=>{const px=b.dataset.px,L=upiList(px);L.splice(+b.dataset.i,1);upiSave(px,L)},
 spCancel:b=>{const px=b.dataset.px,k=b.dataset.k;subClose();if(k==='online'&&!bankLinked(px))['pm_online','qr_online'].forEach(id=>{const el=document.getElementById(px+id);if(el&&el.checked){el.checked=false;pmSync(px,'online',id.startsWith('pm')?'pm':'qr',false)}});
   if(k==='upi'&&!upiList(px).some(a=>a.on!==false))['pm_upi','qr_upi'].forEach(id=>{const el=document.getElementById(px+id);if(el&&el.checked){el.checked=false;pmSync(px,'upi',id.startsWith('pm')?'pm':'qr',false)}})},
 bankSave:b=>{const px=b.dataset.px,g=id=>document.getElementById(id).value.trim(),hn=g('sp_bk_name'),no=g('sp_bk_no').replace(/[\s-]/g,''),no2=g('sp_bk_no2').replace(/[\s-]/g,''),ifsc=g('sp_bk_ifsc').toUpperCase().replace(/\s/g,'');
   if(!hn)return spErr('Add the account holder name');if(!/^\d{9,18}$/.test(no))return spErr('Account number should be 9 to 18 digits (numbers only)');if(no!==no2)return spErr('The two account numbers don’t match');if(!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(ifsc))return spErr('IFSC looks wrong. It is 11 characters, like SBIN0001234');if(!document.getElementById('sp_bk_ok').checked)return spErr('Tick the box to confirm the account');
   const s=(id,v)=>{const el=document.getElementById(px+id);if(el)el.value=v};s('bk_name',hn);s('bk_no',no);s('bk_ifsc',ifsc);const ok=document.getElementById(px+'bk_ok');if(ok)ok.checked=true;
   const sum=document.getElementById(px+'bkSum');if(sum)sum.innerHTML=`<div class="upi-row"><span class="ur-qr">${ic('card',20)}</span><div class="ur-t"><b>${esc(hn)} · ••••${no.slice(-4)}</b><small>${esc(ifsc)} · ready to link when you save</small></div></div>`;const bt=document.getElementById(px+'bkBtn');if(bt)bt.innerHTML=`${ic('edit',16)}Change bank account`;subClose();toast('Bank account added','good')},
 upiSaveB:b=>{const px=b.dataset.px,i=+b.dataset.i,id=document.getElementById('sp_upi').value.trim().replace(/\s/g,''),nm=document.getElementById('sp_upn').value.trim(),L=upiList(px);
   if(!id)return spErr('Add the UPI ID');if(!UPI_RE.test(id))return spErr('UPI ID looks wrong. It should look like name@okaxis');
   /* a saved account always uses the QR made from its UPI ID, so the QR and the ID can never disagree */
   const a={id,name:nm,qr:null,on:document.getElementById('sp_upion').checked};if(i>=0)L[i]=a;else L.push(a);upiSave(px,L);subClose();toast('UPI account saved','good')}});
document.addEventListener('change',e=>{const t=e.target;if(!t.dataset||t.dataset.upion===undefined)return;const px=t.dataset.upion,L=upiList(px);if(L[+t.dataset.i]){L[+t.dataset.i].on=t.checked;upiSave(px,L)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('subpop')){e.stopPropagation();subClose()}},true);

