const NAVHELP=[['Home','Totals for all your functions, things that need attention and this video.'],['Our Events / Functions','Live now, upcoming with a countdown, completed and all done. Tap one to go inside.'],['Guest list','One record per mobile. Invite guests and send thank-you messages.'],['Reminders','Functions you attend to return Moi. Calendar invite and a ringing alarm.'],['Message credits','WhatsApp and SMS receipts use credits. Valid till date shown.']];
const VSTART=[];{let t=0;VSC2.forEach((s,i)=>{VSTART[i]=t;t+=s.d})}
const VTOT=()=>VSC2.reduce((a,s)=>a+s.d,0);
const vIdx=t=>{let i=0;while(i<VSC2.length-1&&t>=VSTART[i+1])i++;return i};
let V2={i:-1,done:new Set(),root:null};
function v2rel(el,root){let x=0,y=0,n=el;while(n&&n!==root){x+=n.offsetLeft;y+=n.offsetTop;n=n.offsetParent}let p=el.parentElement;while(p&&p!==root){y-=p.scrollTop||0;x-=p.scrollLeft||0;p=p.parentElement}return [x+el.offsetWidth/2,y+el.offsetHeight/2]}
function v2cur(sel,jump){const R=V2.root;if(!R)return;const el=R.querySelector(sel),c=R.querySelector('.mk-cur');if(!el||!c)return;const [x,y]=v2rel(el,R);if(jump)c.classList.add('jump');c.style.left=x+'px';c.style.top=y+'px';c.classList.add('on');if(jump){void c.offsetWidth;c.classList.remove('jump')}}
function v2tap(sel,live){v2cur(sel,!live);if(!live)return;const R=V2.root,el=R.querySelector(sel);setTimeout(()=>{const c=R.querySelector('.mk-cur');if(!c)return;const r=document.createElement('i');r.className='mk-rip';r.style.left=c.style.left;r.style.top=c.style.top;R.appendChild(r);setTimeout(()=>r.remove(),700);if(el){el.classList.add('pressed');setTimeout(()=>el.classList.remove('pressed'),260)}},420)}
function v2run(t,live){const sc=VSC2[V2.i],R=V2.root;if(!sc||!sc.steps||!R)return;sc.steps.forEach((s,k)=>{const [st,op,sel,arg,d]=s;if(t<st)return;const dur=op==='type'||op==='count'?(d||0.001):0;const p=dur?Math.min(1,(t-st)/dur):1;if(V2.done.has(k))return;const el=sel&&typeof sel==='string'?R.querySelector(sel):null;
  const fresh=live&&t-st<.5;
  switch(op){case 'cur':v2cur(sel,!fresh);break;case 'tap':v2tap(sel,fresh);break;case 'scr':R.querySelectorAll('.mk-dev').forEach(dv=>{dv.dataset.s=sel});break;
   case 'type':if(el){el.textContent=arg.slice(0,Math.round(p*arg.length));el.classList.toggle('typing',p<1);if(p<1)return}break;
   case 'on':if(el)el.classList.add('on');break;case 'off':if(el)el.classList.remove('on');break;case 'cls':if(el)el.classList.add(arg);break;
   case 'count':if(el){const v=Math.round(arg[0]+(arg[1]-arg[0])*p);el.textContent='₹'+v.toLocaleString('en-IN');if(p<1)return}break;
   case 'navto':{R.querySelectorAll('.mk-nav').forEach((n,i)=>n.classList.toggle('on',i===sel));const h=R.querySelector('#n-h'),pp=R.querySelector('#n-p');if(h)h.textContent=NAVHELP[sel][0];if(pp)pp.textContent=NAVHELP[sel][1]}break}
  V2.done.add(k)})}
function vidScene(i){const st=document.getElementById('vidStage');if(!st)return;vid.i=i;const sc=VSC2[i],s=VSUB[vLg()][i];V2={i,done:new Set(),root:null};
  if(sc.k==='intro'||sc.k==='end'){st.innerHTML=`<div class="vs vs-${sc.k}"><div class="vs-glow"></div><span class="vs-mark">${mpMark()}</span><h2 class="vs-brand">${MPW()}</h2><p class="vs-tag">Grow Together</p><p class="vs-tt">${esc(s[0])}</p>${sc.k==='intro'?`<div class="vs-chips">${['plus','users','cash','msg','qr','list','bill','chart'].map((k,j)=>`<span style="animation-delay:${.4+j*.14}s">${ic(k,26)}</span>`).join('')}</div>`:`<div class="vs-end-b">${me&&me.role==='admin'?`<button class="btn btn-primary" data-act="vidCreate">${ic('plus',18)}Create my first function</button>`:''}${me?`<button class="btn btn-white" data-act="vidTour">Show me around</button>`:`<button class="btn btn-primary" data-act="vidSignup">${ic('arrow',18)}Start free</button>`}</div>`}</div>`}
  else{const dev=sc.dev==='scan'?`<div class="mk-scanwrap">${sc.html}</div>`:`<div class="mk-dev ${sc.dev}" data-s="0">${sc.html}</div>`;
   st.innerHTML=`<div class="vs vs-step v2"><div class="vs-l"><span class="vs-n">${i}</span><span class="vs-ic">${ic(VSIC[sc.k],30)}</span><p class="vs-tt">${esc(s[0])}</p><div class="vs-dots">${VSC2.slice(1,-1).map((_,j)=>`<i class="${j+1===i?'on':j+1<i?'done':''}"></i>`).join('')}</div></div><div class="vs-r">${dev}</div><i class="mk-cur"><svg viewBox="0 0 24 24" width="34" height="34"><path d="M9 11V5.5a1.5 1.5 0 0 1 3 0V11m0-1.5a1.5 1.5 0 0 1 3 0V12m0-1a1.5 1.5 0 0 1 3 0v4.5a6 6 0 0 1-6 6h-1.2a6 6 0 0 1-4.9-2.6L4.2 16a1.6 1.6 0 0 1 2.5-2L9 16.2" fill="#fff" stroke="#1D1A4A" stroke-width="1.5" stroke-linejoin="round"/></svg></i></div>`;
   V2.root=st.querySelector('.vs');const g=V2.root.querySelector('.mk-guest');if(g)g.dataset.s='0'}
  st.classList.toggle('still',!vid.play);vidSubT();vidUI()}
function vidUI(){const T=VTOT(),el=Math.min(T,vid.el),f=document.getElementById('vidFill'),tm=document.getElementById('vidTm'),b=document.getElementById('vidPlayB');if(f)f.style.width=el/T*100+'%';if(tm)tm.textContent=vfmt(el)+' / '+vfmt(T);if(b){b.innerHTML=vid.play?VPAUSE:VPLAY;b.setAttribute('aria-label',vid.play?'Pause':'Play')}const st=document.getElementById('vidStage');if(st)st.classList.toggle('paused',!vid.play)}
function vidTick(ts){if(!vid.on||!vid.play)return;if(!vid.last)vid.last=ts;vid.el+=Math.min(.25,(ts-vid.last)/1000);vid.last=ts;const T=VTOT();
  if(vid.el>=T-.05){vid.el=T-.01;vid.play=false;vidUI();musicStop(1.5);return}const i=vIdx(vid.el);if(i!==vid.i)vidScene(i);v2run(vid.el-VSTART[i],true);vidUI();vid.raf=requestAnimationFrame(vidTick)}
function vidPlay(on){vid.play=on;vid.last=0;cancelAnimationFrame(vid.raf);if(on){const st=document.getElementById('vidStage');if(st)st.classList.remove('still');if(vid.el>=VTOT()-.1){vid.el=0;vidScene(0)}if(vid.music)musicStart();vid.raf=requestAnimationFrame(vidTick)}else musicStop(.4);vidUI()}
