/* ---------- words: “Moi” in other languages, and the English receive label ---------- */
const MOIW={hi:[/मोई/g,'शगुन'],mr:[/मोई/g,'आहेर'],te:[/మొయ్/g,'చదివింపు'],ml:[/മൊയ്/g,'സമ്മാനം'],kn:[/ಮೊಯ್/g,'ಮುಯ್ಯಿ'],gu:[/મોઈ/g,'ચાંદલો'],bn:[/মোই/g,'উপহার'],pa:[/ਮੋਈ/g,'ਸ਼ਗਨ'],or:[/ମୋଇ/g,'ଉପହାର']};
const MOIEN=[[/^(\s*)Receive Moi(\s*)$/,'$1Receive Moi / Cash or Gift$2'],[/^(\s*)Receive Moi \/ Gift(\s*)$/,'$1Receive Moi / Cash or Gift$2']];
function wordFix(root){if(!root)return;const R=UIL==='ta'?WF_TA:UIL==='en'?WF_EN:null,MW=MOIW[UIL];const nodes=[];
  if(root.nodeType===3)nodes.push(root);else if(root.nodeType===1){if(root.closest&&root.closest(WF_SKIP))return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode()))nodes.push(n)}
  nodes.forEach(nd=>{const v=nd.nodeValue;if(!v||v.length<2)return;const p=nd.parentElement;if(!p||p.closest(WF_SKIP)||p.isContentEditable)return;let t=v;
    if(R&&(UIL!=='en'||/vent|oid|OID|Moi/.test(v))){R.forEach(([re,s])=>{t=t.replace(re,s)});if(UIL==='en'&&!p.closest('.bnav,.qa-grid,.q-act'))MOIEN.forEach(([re,s])=>{t=t.replace(re,s)})}
    if(MW){t=t.replace(MW[0],MW[1]).replace(/\bMoi\b(?!\s*Poin)/g,MW[1])}
    if(t!==v)nd.nodeValue=t})}

