function mig46(){if(S.v46)return;const pr=P().pricing;if(pr&&Array.isArray(pr.packs))pr.packs=pr.packs.filter(q=>q>=100);if(pr&&pr.costWa==null)pr.costWa=+(pr.cost??0.35);if(pr&&pr.costSms==null)pr.costSms=0.25;
  S.users.filter(u=>u.role!=='admin'&&u.role!=='platform'&&u.email&&u.username!==u.email.toLowerCase()&&!S.users.some(x=>x!==u&&x.username===u.email.toLowerCase())).forEach(u=>{u.oldUser=u.username;u.username=u.email.toLowerCase()});S.v46=1}

/* ---------- “Other” choices: type it, see what others typed, saved for next time ---------- */
function otherBox(id,kind,show){const lbl={ctype:'Which function? Type it',crel:'Which relation? Type it',xcat:'Which expense? Type it'}[kind],ph={ctype:'e.g. Seemantham, Upanayanam',crel:'e.g. Co-brother, Sambandhi',xcat:'e.g. Flowers, Mehendi, Band set'}[kind];
  return `<label class="field other-box ac-field full" id="${id}_ow" ${show?'':'hidden'}><span>${lbl} <i>*</i></span><input id="${id}_o" data-ac="o_${kind}" autocomplete="off" placeholder="${ph}"><div class="ac-list" id="ac-${id}_o" role="listbox" hidden></div><small class="muted">Start typing — names others have used appear. It is saved for next time.</small></label>`}
function saveCustom(kind,val,A){val=String(val||'').trim();if(!val||!OTHK[kind])return;if(OTHB[kind]().includes(val))return;const key=OTHK[kind],M=P()[key]=P()[key]||{};const k=Object.keys(M).find(x=>x.toLowerCase()===val.toLowerCase())||val;M[k]=(M[k]||0)+1;if(A){const L=A[key]=A[key]||[];if(!L.some(x=>x.toLowerCase()===k.toLowerCase()))L.push(k)}}
function acSource(kind){const acc=curAcc(),gb=guestBook(acc.id);
  if(kind==='place')return [...new Set([...gb.map(g=>g.place).filter(Boolean),acc.city,...masterPlaces(),...PLACES0].filter(Boolean))];
  if(kind==='des')return [...new Set([...gb.map(g=>g.des).filter(Boolean),...masterDes(),...DES0].filter(Boolean))];
  if(/^o_/.test(kind))return otherList(kind.slice(2));return gb}

